"use client";

import { useState, useRef, useEffect } from "react";
import { createPortal } from "react-dom";
import { useRouter, usePathname, useSearchParams } from "next/navigation";
import { Calendar as CalendarIcon, ChevronLeft, ChevronRight } from "lucide-react";

interface DateRangePickerProps {
  initialStart?: string;
  initialEnd?: string;
}

const MONTH_NAMES = [
  "Januari", "Februari", "Maret", "April", "Mei", "Juni",
  "Juli", "Agustus", "September", "Oktober", "November", "Desember"
];

const WEEK_DAYS = ["Sen", "Sel", "Rab", "Kam", "Jum", "Sab", "Min"];

export default function DateRangePicker({ initialStart, initialEnd }: DateRangePickerProps) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  // Fixed-position coords so the dropdown escapes overflow:auto scroll containers
  const [dropPos, setDropPos] = useState<{ top: number; right: number } | null>(null);

  function openWithPos() {
    if (triggerRef.current) {
      const r = triggerRef.current.getBoundingClientRect();
      setDropPos({ top: r.bottom + 6, right: window.innerWidth - r.right });
    }
    setIsOpen((v) => !v);
  }

  // Temporary selection state for custom calendar selection
  const [tempStart, setTempStart] = useState<Date | null>(
    initialStart ? new Date(initialStart) : null
  );
  const [tempEnd, setTempEnd] = useState<Date | null>(
    initialEnd ? new Date(initialEnd) : null
  );
  const [hoveredDate, setHoveredDate] = useState<Date | null>(null);

  // Active month in the calendar view
  const [currentMonth, setCurrentMonth] = useState<Date>(
    initialStart ? new Date(initialStart) : new Date()
  );

  // Sync state if initial props change
  useEffect(() => {
    setTempStart(initialStart ? new Date(initialStart) : null);
    setTempEnd(initialEnd ? new Date(initialEnd) : null);
  }, [initialStart, initialEnd]);

  // Handle outside click to close dropdown
  // The dropdown is fixed-positioned (outside containerRef), so we track it separately.
  const dropdownRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const t = event.target as Node;
      const insideTrigger = containerRef.current?.contains(t);
      const insideDropdown = dropdownRef.current?.contains(t);
      if (!insideTrigger && !insideDropdown) setIsOpen(false);
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Handle escape key to close dropdown
  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    }
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Formatting dates for display
  const formatDateISO = (d: Date) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };

  const formatDateDisplay = (d: Date) => {
    return d.toLocaleDateString("id-ID", { day: "numeric", month: "short", year: "numeric" });
  };

  const activeRangeLabel = (() => {
    if (initialStart && initialEnd) {
      const start = new Date(initialStart);
      const end = new Date(initialEnd);
      if (formatDateISO(start) === formatDateISO(end)) {
        return formatDateDisplay(start);
      }
      return `${formatDateDisplay(start)} - ${formatDateDisplay(end)}`;
    }
    if (initialStart) {
      return `Mulai dari ${formatDateDisplay(new Date(initialStart))}`;
    }
    if (initialEnd) {
      return `Hingga ${formatDateDisplay(new Date(initialEnd))}`;
    }
    return "14 Hari Terakhir"; // default fallback in dashboard
  })();

  // Apply selected dates to URL params
  const applyDates = (start?: Date, end?: Date) => {
    const params = new URLSearchParams(searchParams.toString());
    if (start) {
      params.set("start", formatDateISO(start));
    } else {
      params.delete("start");
    }

    if (end) {
      params.set("end", formatDateISO(end));
    } else {
      params.delete("end");
    }

    setIsOpen(false);
    router.push(`${pathname}?${params.toString()}`);
  };

  const applyPreset = (preset: "today" | "7days" | "14days" | "30days" | "thisMonth" | "allTime") => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    let start: Date | undefined;
    let end: Date | undefined = new Date(today);

    if (preset === "today") {
      start = new Date(today);
    } else if (preset === "7days") {
      start = new Date(today.getTime() - 6 * 24 * 60 * 60 * 1000);
    } else if (preset === "14days") {
      start = new Date(today.getTime() - 13 * 24 * 60 * 60 * 1000);
    } else if (preset === "30days") {
      start = new Date(today.getTime() - 29 * 24 * 60 * 60 * 1000);
    } else if (preset === "thisMonth") {
      start = new Date(today.getFullYear(), today.getMonth(), 1);
    } else if (preset === "allTime") {
      start = undefined;
      end = undefined;
    }

    setTempStart(start || null);
    setTempEnd(end || null);
    applyDates(start, end);
  };

  // Generate calendar days
  const calendarCells = (() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();

    const firstDay = new Date(year, month, 1);
    const firstDayOfWeek = firstDay.getDay(); // 0 = Sun, 1 = Mon ...
    const startPadding = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1;

    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const prevMonthDays = new Date(year, month, 0).getDate();

    const cells: { date: Date; isCurrentMonth: boolean }[] = [];

    // Prev month padding
    for (let i = startPadding - 1; i >= 0; i--) {
      cells.push({
        date: new Date(year, month - 1, prevMonthDays - i),
        isCurrentMonth: false,
      });
    }

    // Current month
    for (let i = 1; i <= daysInMonth; i++) {
      cells.push({
        date: new Date(year, month, i),
        isCurrentMonth: true,
      });
    }

    // Next month padding
    const nextPadding = 42 - cells.length;
    for (let i = 1; i <= nextPadding; i++) {
      cells.push({
        date: new Date(year, month + 1, i),
        isCurrentMonth: false,
      });
    }

    return cells;
  })();

  const handleDayClick = (date: Date) => {
    if (!tempStart || (tempStart && tempEnd)) {
      setTempStart(date);
      setTempEnd(null);
    } else if (tempStart && !tempEnd) {
      if (date < tempStart) {
        setTempStart(date);
      } else {
        setTempEnd(date);
      }
    }
  };

  const isSelected = (date: Date) => {
    if (tempStart && formatDateISO(date) === formatDateISO(tempStart)) return "start";
    if (tempEnd && formatDateISO(date) === formatDateISO(tempEnd)) return "end";
    return null;
  };

  const isInRange = (date: Date) => {
    if (tempStart && tempEnd) {
      return date > tempStart && date < tempEnd;
    }
    if (tempStart && !tempEnd && hoveredDate) {
      return date > tempStart && date < hoveredDate;
    }
    return false;
  };

  const changeMonth = (direction: number) => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + direction, 1));
  };

  return (
    <div ref={containerRef} className="relative z-30">
      {/* Date trigger button */}
      <button
        ref={triggerRef}
        onClick={openWithPos}
        className="press flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition-all cursor-pointer"
        style={{
          background: "#0D1829",
          color: "#E9EEF6",
          border: "1px solid rgba(255, 255, 255, 0.08)",
          boxShadow: "0 4px 12px rgba(0, 0, 0, 0.15)"
        }}
      >
        <CalendarIcon size={16} className="opacity-70 text-orange-500" style={{ color: "#FD5002" }} />
        <span>{activeRangeLabel}</span>
      </button>

      {/* Dropdown panel — portalled to body to escape all ancestor stacking contexts */}
      {isOpen && dropPos && typeof document !== "undefined" && createPortal(
        <div
          ref={dropdownRef}
          className="rounded-2xl flex flex-col md:flex-row overflow-hidden shadow-2xl dash-reveal"
          style={{
            position: "fixed",
            top: dropPos.top,
            right: dropPos.right,
            zIndex: 9999,
            background: "rgba(13, 24, 41, 0.98)",
            backdropFilter: "blur(16px)",
            WebkitBackdropFilter: "blur(16px)",
            border: "1px solid rgba(255, 255, 255, 0.10)",
            width: "max-content",
            maxWidth: "calc(100vw - 16px)",
            boxShadow: "0 24px 48px rgba(0, 0, 0, 0.5)",
          }}
        >
          {/* Left panel: Presets */}
          <div
            className="w-full md:w-[170px] shrink-0 p-3 space-y-1 flex flex-row md:flex-col overflow-x-auto md:overflow-x-visible no-scrollbar"
            style={{
              borderRight: "1px solid rgba(255, 255, 255, 0.06)",
              borderBottom: "1px solid rgba(255, 255, 255, 0.06)",
            }}
          >
            {[
              { id: "today", label: "Hari Ini" },
              { id: "7days", label: "7 Hari Terakhir" },
              { id: "14days", label: "14 Hari Terakhir" },
              { id: "30days", label: "30 Hari Terakhir" },
              { id: "thisMonth", label: "Bulan Ini" },
              { id: "allTime", label: "Semua Waktu" }
            ].map((p) => (
              <button
                key={p.id}
                onClick={() => applyPreset(p.id as any)}
                className="w-max md:w-full text-left px-3 py-2 rounded-lg text-xs font-semibold hover:bg-white/5 transition-colors shrink-0 cursor-pointer"
                style={{ color: "#9FB6D1" }}
              >
                {p.label}
              </button>
            ))}
          </div>

          {/* Right panel: Calendar picker */}
          <div className="p-4 w-[290px] md:w-[310px] shrink-0">
            {/* Calendar header */}
            <div className="flex items-center justify-between mb-4">
              <span className="text-sm font-bold" style={{ color: "#E9EEF6" }}>
                {MONTH_NAMES[currentMonth.getMonth()]} {currentMonth.getFullYear()}
              </span>
              <div className="flex gap-1">
                <button
                  onClick={() => changeMonth(-1)}
                  className="press p-1.5 rounded-lg hover:bg-white/5 transition-colors cursor-pointer"
                  style={{ color: "#5A7898" }}
                >
                  <ChevronLeft size={16} />
                </button>
                <button
                  onClick={() => changeMonth(1)}
                  className="press p-1.5 rounded-lg hover:bg-white/5 transition-colors cursor-pointer"
                  style={{ color: "#5A7898" }}
                >
                  <ChevronRight size={16} />
                </button>
              </div>
            </div>

            {/* Days of week */}
            <div className="grid grid-cols-7 gap-1 text-center mb-1">
              {WEEK_DAYS.map((d) => (
                <span key={d} className="text-[10px] font-bold uppercase tracking-wider" style={{ color: "#5A7898" }}>
                  {d}
                </span>
              ))}
            </div>

            {/* Calendar grid */}
            <div className="grid grid-cols-7 gap-1">
              {calendarCells.map((cell, idx) => {
                const sel = isSelected(cell.date);
                const range = isInRange(cell.date);
                const isToday = formatDateISO(cell.date) === formatDateISO(new Date());

                return (
                  <button
                    key={idx}
                    onClick={() => handleDayClick(cell.date)}
                    onMouseEnter={() => tempStart && !tempEnd && setHoveredDate(cell.date)}
                    onMouseLeave={() => setHoveredDate(null)}
                    className="h-8 rounded-lg flex items-center justify-center text-xs font-semibold relative transition-colors cursor-pointer"
                    style={{
                      color: sel ? "#FFF" : !cell.isCurrentMonth ? "#374F6B" : "#9FB6D1",
                      background: sel
                        ? "#FD5002"
                        : range
                        ? "rgba(253, 80, 2, 0.12)"
                        : isToday
                        ? "rgba(255, 255, 255, 0.04)"
                        : "transparent",
                      border: isToday && !sel ? "1px solid rgba(255, 255, 255, 0.15)" : "none"
                    }}
                  >
                    <span className="relative z-10">{cell.date.getDate()}</span>
                    {/* Visual dot background connection */}
                    {sel && tempStart && tempEnd && (
                      <span
                        className="absolute inset-y-0 w-4 pointer-events-none"
                        style={{
                          background: "rgba(253, 80, 2, 0.12)",
                          left: sel === "end" ? 0 : "auto",
                          right: sel === "start" ? 0 : "auto",
                          zIndex: 0
                        }}
                      />
                    )}
                  </button>
                );
              })}
            </div>

            {/* Action buttons */}
            <div className="flex gap-2 mt-4 pt-3" style={{ borderTop: "1px solid rgba(255, 255, 255, 0.06)" }}>
              <button
                onClick={() => setIsOpen(false)}
                className="flex-1 py-2 rounded-xl text-xs font-bold hover:bg-white/5 transition-colors cursor-pointer"
                style={{ color: "#5A7898" }}
              >
                Batal
              </button>
              <button
                onClick={() => applyDates(tempStart || undefined, tempEnd || undefined)}
                disabled={!tempStart}
                className="flex-1 py-2 rounded-xl text-xs font-bold text-white transition-all disabled:opacity-50 cursor-pointer"
                style={{
                  background: "#FD5002",
                  boxShadow: "0 4px 12px rgba(253, 80, 2, 0.25)"
                }}
              >
                Terapkan
              </button>
            </div>
          </div>
        </div>,
        document.body
      )}
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { createPortal } from "react-dom";
import { Download, FileSpreadsheet, FileText, Loader2, ChevronDown } from "lucide-react";
import { getSalesExport, type SalesExportRow } from "@/lib/dashboard-actions";
import { escapeHtml, formatRupiah } from "@/lib/format";

function fmtDateTime(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleString("id-ID", { day: "2-digit", month: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

function rangeLabel(start?: string, end?: string): string {
  const f = (s: string) => new Date(s).toLocaleDateString("id-ID", { day: "numeric", month: "short", year: "numeric" });
  if (start && end) return `${f(start)} - ${f(end)}`;
  if (start) return `Sejak ${f(start)}`;
  if (end) return `Hingga ${f(end)}`;
  return "14 hari terakhir";
}

const PAY_LABEL: Record<string, string> = { qris: "QRIS", cash: "Tunai" };
const STATUS_LABEL: Record<string, string> = { received: "Baru", preparing: "Diproses", ready: "Siap" };

function csvCell(v: string | number): string {
  const s = String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function downloadCsv(rows: SalesExportRow[], cafeName: string, start?: string, end?: string) {
  const header = ["No. Pesanan", "Tanggal", "Meja", "Item", "Jumlah Item", "Total (Rp)", "Metode Bayar", "Status Bayar", "Status Pesanan"];
  const lines = rows.map((r) => [
    r.id_order, fmtDateTime(r.created_at), r.table_number, r.items_summary,
    r.item_count, r.total, PAY_LABEL[r.payment_method] ?? r.payment_method,
    r.payment_status === "paid" ? "Lunas" : "Belum", STATUS_LABEL[r.status] ?? r.status,
  ].map(csvCell).join(","));
  const totalSum = rows.reduce((n, r) => n + r.total, 0);
  const meta = [`${cafeName} - Laporan Penjualan`, `Periode: ${rangeLabel(start, end)}`, `Total transaksi: ${rows.length}`, `Total pendapatan: ${totalSum}`, ""];
  const csv = "﻿" + [...meta.map((m) => csvCell(m)), header.join(","), ...lines].join("\n");

  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `Laporan-${cafeName.replace(/\s+/g, "-")}-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

/** Laporan dirakit sebagai string HTML lalu ditulis via document.write ke
 *  iframe same-origin — SEMUA teks yang disisipkan harus lewat escapeHtml.
 *  table_number berasal dari POST /api/orders yang publik. */
export function buildSalesReportHtml(rows: SalesExportRow[], cafeName: string, start?: string, end?: string): string {
  const totalSum = rows.reduce((n, r) => n + r.total, 0);
  const paidCount = rows.filter((r) => r.payment_status === "paid").length;
  const cafe = escapeHtml(cafeName);
  const body = rows.map((r, i) => `
    <tr>
      <td class="num">${i + 1}</td>
      <td>${escapeHtml(fmtDateTime(r.created_at))}</td>
      <td>${escapeHtml(String(r.table_number ?? ""))}</td>
      <td class="wrap">${escapeHtml(String(r.items_summary ?? "")) || "-"}</td>
      <td class="num">${r.item_count}</td>
      <td class="num strong">${formatRupiah(r.total)}</td>
      <td>${PAY_LABEL[r.payment_method] ?? "-"}</td>
      <td>${r.payment_status === "paid" ? "Lunas" : "Belum"}</td>
    </tr>`).join("");

  return `<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><title>Laporan Penjualan - ${cafe}</title>
  <style>
    *{margin:0;padding:0;box-sizing:border-box}
    body{font-family:-apple-system,'Segoe UI',Roboto,sans-serif;color:#15233a;padding:32px 28px;font-size:12px}
    .head{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:2px solid #15233a;padding-bottom:14px;margin-bottom:6px}
    h1{font-size:20px;font-weight:800;letter-spacing:-0.01em}
    .sub{font-size:11px;color:#5A7898;margin-top:3px}
    .brand{font-size:11px;font-weight:700;color:#FD5002;text-align:right}
    .cards{display:flex;gap:10px;margin:16px 0}
    .card{flex:1;border:1px solid #e2e8f0;border-radius:10px;padding:10px 12px}
    .card .l{font-size:9.5px;text-transform:uppercase;letter-spacing:0.06em;color:#5A7898;font-weight:700}
    .card .v{font-size:16px;font-weight:800;margin-top:3px;letter-spacing:-0.01em}
    table{width:100%;border-collapse:collapse;margin-top:4px}
    th{text-align:left;font-size:9.5px;text-transform:uppercase;letter-spacing:0.05em;color:#5A7898;
       border-bottom:1.5px solid #cbd5e1;padding:7px 6px}
    td{padding:7px 6px;border-bottom:1px solid #eef2f7;vertical-align:top}
    td.num,th.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
    td.strong{font-weight:700}
    td.wrap{max-width:240px}
    tfoot td{border-top:2px solid #15233a;border-bottom:none;font-weight:800;font-size:13px;padding-top:9px}
    .foot{margin-top:18px;font-size:10px;color:#94a3b8;text-align:center}
    @media print{ body{padding:0} @page{margin:14mm 12mm;size:A4} }
  </style></head><body>
    <div class="head">
      <div><h1>${cafe}</h1><div class="sub">Laporan Penjualan · ${escapeHtml(rangeLabel(start, end))}</div></div>
      <div class="brand">3Diner POS<div style="color:#94a3b8;font-weight:500;margin-top:2px">Dicetak ${new Date().toLocaleString("id-ID", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" })}</div></div>
    </div>
    <div class="cards">
      <div class="card"><div class="l">Total Pendapatan</div><div class="v">${formatRupiah(totalSum)}</div></div>
      <div class="card"><div class="l">Jumlah Transaksi</div><div class="v">${rows.length}</div></div>
      <div class="card"><div class="l">Sudah Lunas</div><div class="v">${paidCount} / ${rows.length}</div></div>
    </div>
    <table>
      <thead><tr><th class="num">#</th><th>Tanggal</th><th>Meja</th><th>Item</th><th class="num">Qty</th><th class="num">Total</th><th>Bayar</th><th>Status</th></tr></thead>
      <tbody>${body || `<tr><td colspan="8" style="text-align:center;color:#94a3b8;padding:24px">Tidak ada transaksi pada periode ini.</td></tr>`}</tbody>
      ${rows.length ? `<tfoot><tr><td colspan="5">TOTAL</td><td class="num">${formatRupiah(totalSum)}</td><td colspan="2"></td></tr></tfoot>` : ""}
    </table>
    <div class="foot">Laporan dihasilkan otomatis oleh 3Diner · ${cafe}</div>
  </body></html>`;
}

function printPdf(rows: SalesExportRow[], cafeName: string, start?: string, end?: string) {
  const html = buildSalesReportHtml(rows, cafeName, start, end);

  const iframe = document.createElement("iframe");
  iframe.style.cssText = "position:fixed;top:-9999px;left:-9999px;width:1px;height:1px;border:none;opacity:0;";
  document.body.appendChild(iframe);
  const doc = iframe.contentDocument ?? iframe.contentWindow?.document;
  if (!doc) { document.body.removeChild(iframe); return; }
  doc.open(); doc.write(html); doc.close();
  setTimeout(() => {
    iframe.contentWindow?.focus();
    iframe.contentWindow?.print();
    setTimeout(() => { if (document.body.contains(iframe)) document.body.removeChild(iframe); }, 1500);
  }, 400);
}

export default function ExportReport({ start, end }: { start?: string; end?: string }) {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState<"csv" | "pdf" | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [mounted, setMounted] = useState(false);
  const [pos, setPos] = useState<{ top: number; right: number }>({ top: 0, right: 0 });
  const wrapRef = useRef<HTMLDivElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => setMounted(true), []);

  // Anchor the portal menu just below the button, aligned to its right edge.
  const place = useCallback(() => {
    const r = wrapRef.current?.getBoundingClientRect();
    if (r) setPos({ top: r.bottom + 8, right: window.innerWidth - r.right });
  }, []);

  useEffect(() => {
    if (!open) return;
    place();
    const onDoc = (e: MouseEvent) => {
      const t = e.target as Node;
      if (!wrapRef.current?.contains(t) && !menuRef.current?.contains(t)) setOpen(false);
    };
    const onMove = () => place();
    document.addEventListener("mousedown", onDoc);
    window.addEventListener("resize", onMove);
    window.addEventListener("scroll", onMove, true);
    return () => {
      document.removeEventListener("mousedown", onDoc);
      window.removeEventListener("resize", onMove);
      window.removeEventListener("scroll", onMove, true);
    };
  }, [open, place]);

  async function run(kind: "csv" | "pdf") {
    setError(null);
    setLoading(kind);
    try {
      const res = await getSalesExport(start, end);
      if (res.error) throw new Error(res.error);
      const rows = res.rows ?? [];
      const name = res.cafeName ?? "3Diner";
      if (rows.length === 0) { setError("Tidak ada transaksi pada periode ini."); return; }
      if (kind === "csv") downloadCsv(rows, name, start, end);
      else printPdf(rows, name, start, end);
      setOpen(false);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Gagal mengekspor data");
    } finally {
      setLoading(null);
    }
  }

  return (
    <div className="relative" ref={wrapRef}>
      <button
        onClick={() => setOpen((o) => !o)}
        className="dash-press inline-flex items-center gap-2 px-3.5 py-2.5 rounded-xl text-sm font-semibold"
        style={{ background: "#132136", color: "#E9EEF6", border: "1px solid rgba(255,255,255,0.1)" }}
      >
        <Download size={15} /> Ekspor
        <ChevronDown size={14} style={{ color: "#5A7898", transform: open ? "rotate(180deg)" : "none", transition: "transform 160ms ease-out" }} />
      </button>

      {open && mounted && createPortal(
        <div
          ref={menuRef}
          className="fixed w-60 rounded-2xl p-1.5 z-[100]"
          style={{ top: pos.top, right: pos.right, background: "#0D1829", border: "1px solid rgba(255,255,255,0.1)", boxShadow: "0 18px 50px rgba(0,0,0,0.5)", animation: "ord-toast-in .2s cubic-bezier(0.22,1,0.36,1)" }}
        >
          <style>{`@keyframes ord-toast-in { from { opacity:0; transform: translateY(-6px) } to { opacity:1; transform:none } }`}</style>
          <MenuRow
            icon={<FileSpreadsheet size={17} style={{ color: "#22D3A6" }} />}
            title="Unduh CSV"
            desc="Buka di Excel / Sheets"
            loading={loading === "csv"}
            onClick={() => run("csv")}
          />
          <MenuRow
            icon={<FileText size={17} style={{ color: "#FD5002" }} />}
            title="Cetak / PDF"
            desc="Laporan rapi untuk arsip"
            loading={loading === "pdf"}
            onClick={() => run("pdf")}
          />
          {error && (
            <p className="text-[11px] px-3 py-2 mt-1 rounded-lg" style={{ color: "#FCA5A5", background: "rgba(239,68,68,0.08)" }}>
              {error}
            </p>
          )}
        </div>,
        document.body
      )}
    </div>
  );
}

function MenuRow({ icon, title, desc, loading, onClick }: { icon: React.ReactNode; title: string; desc: string; loading: boolean; onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      disabled={loading}
      className="w-full flex items-center gap-3 p-2.5 rounded-xl text-left transition-colors hover:bg-white/[0.04] disabled:opacity-60"
    >
      <span className="w-9 h-9 rounded-lg inline-flex items-center justify-center shrink-0" style={{ background: "#132136" }}>
        {loading ? <Loader2 size={16} className="animate-spin" style={{ color: "#9FB6D1" }} /> : icon}
      </span>
      <span className="min-w-0">
        <span className="block text-sm font-semibold" style={{ color: "#E9EEF6" }}>{title}</span>
        <span className="block text-[11px]" style={{ color: "#5A7898" }}>{desc}</span>
      </span>
    </button>
  );
}

"use client";

import { useRef, useState, useTransition, useCallback, useEffect } from "react";
import { createPortal } from "react-dom";
import {
  Sparkles,
  UploadCloud,
  X,
  Trash2,
  CheckCircle2,
  Loader2,
  FileText,
  AlertCircle,
} from "lucide-react";
import { bulkCreateMenus, type DraftMenuInput } from "@/lib/dashboard-actions";

interface Draft extends DraftMenuInput {
  _id: string;
  nama_menu: string;
  harga_menu: number;
  category: string;
  description_menu: string;
}

type Stage = "idle" | "processing" | "review" | "done";

const C = {
  bg: "#0D1829",
  card: "#132136",
  border: "rgba(255,255,255,0.07)",
  text: "#E9EEF6",
  muted: "#5A7898",
  orange: "#FD5002",
  green: "#22D3A6",
};

let _seq = 0;
const uid = () => `d${Date.now()}_${_seq++}`;

export default function MenuExtractor() {
  const [open, setOpen] = useState(false);
  const [stage, setStage] = useState<Stage>("idle");
  const [progress, setProgress] = useState(0);
  const [drafts, setDrafts] = useState<Draft[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [fileName, setFileName] = useState<string>("");
  const [insertedCount, setInsertedCount] = useState(0);
  const [dragOver, setDragOver] = useState(false);
  const [pending, startTransition] = useTransition();
  const [mounted, setMounted] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const progressTimer = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => setMounted(true), []);

  // Lock body scroll while the overlay is open.
  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = prev; };
  }, [open]);

  const reset = useCallback(() => {
    setStage("idle");
    setProgress(0);
    setDrafts([]);
    setError(null);
    setFileName("");
    setInsertedCount(0);
    if (progressTimer.current) clearInterval(progressTimer.current);
  }, []);

  function closeModal() {
    setOpen(false);
    setTimeout(reset, 200);
  }

  async function handleFile(file: File) {
    setError(null);
    setFileName(file.name);
    setStage("processing");
    setProgress(6);

    // Fake progress crawl up to 90% while waiting on the API
    progressTimer.current = setInterval(() => {
      setProgress((p) => (p < 90 ? p + Math.max(1, Math.round((90 - p) / 12)) : p));
    }, 320);

    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch("/api/menu/extract", { method: "POST", body: fd });
      const data = await res.json();
      if (progressTimer.current) clearInterval(progressTimer.current);

      if (!res.ok) throw new Error(data.error || "Gagal mengekstrak menu");

      const items: Draft[] = (data.menus ?? []).map((m: DraftMenuInput) => ({
        _id: uid(),
        nama_menu: m.nama_menu ?? "",
        harga_menu: Number(m.harga_menu) || 0,
        category: m.category ?? "Lainnya",
        description_menu: m.description_menu ?? "",
      }));

      setProgress(100);
      setTimeout(() => {
        setDrafts(items);
        setStage("review");
      }, 320);
    } catch (e: unknown) {
      if (progressTimer.current) clearInterval(progressTimer.current);
      setError(e instanceof Error ? e.message : "Terjadi kesalahan");
      setStage("idle");
      setProgress(0);
    }
  }

  function onPick(e: React.ChangeEvent<HTMLInputElement>) {
    const f = e.target.files?.[0];
    if (f) handleFile(f);
    e.target.value = "";
  }

  function onDrop(e: React.DragEvent) {
    e.preventDefault();
    setDragOver(false);
    const f = e.dataTransfer.files?.[0];
    if (f) handleFile(f);
  }

  function updateDraft(id: string, patch: Partial<Draft>) {
    setDrafts((prev) => prev.map((d) => (d._id === id ? { ...d, ...patch } : d)));
  }
  function removeDraft(id: string) {
    setDrafts((prev) => prev.filter((d) => d._id !== id));
  }

  function save() {
    const payload: DraftMenuInput[] = drafts
      .filter((d) => d.nama_menu.trim())
      .map((d) => ({
        nama_menu: d.nama_menu.trim(),
        harga_menu: d.harga_menu,
        category: d.category.trim() || null,
        description_menu: d.description_menu.trim() || null,
      }));
    if (payload.length === 0) {
      setError("Tidak ada item valid untuk disimpan.");
      return;
    }
    setError(null);
    startTransition(async () => {
      const res = await bulkCreateMenus(payload);
      if (res.error) {
        setError(res.error);
        return;
      }
      setInsertedCount(res.inserted ?? payload.length);
      setStage("done");
    });
  }

  return (
    <>
      {/* Trigger button */}
      <button
        onClick={() => setOpen(true)}
        className="dash-press inline-flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold"
        style={{ background: C.card, color: C.text, border: `1px solid rgba(253,80,2,0.35)` }}
      >
        <Sparkles size={16} style={{ color: C.orange }} /> Ekstrak Menu via AI
      </button>

      {!open || !mounted ? null : createPortal(
        <div
          className="fixed inset-0 z-[100] flex items-center justify-center p-4 me-overlay"
          style={{ background: "rgba(5,10,20,0.72)", backdropFilter: "blur(6px)" }}
          onClick={closeModal}
        >
          <style>{`
            @keyframes me-fade { from { opacity: 0 } to { opacity: 1 } }
            @keyframes me-pop { from { opacity: 0; transform: translateY(12px) scale(0.98) } to { opacity: 1; transform: none } }
            .me-overlay { animation: me-fade .18s ease-out }
            .me-dialog { animation: me-pop .26s cubic-bezier(0.22,1,0.36,1) }
          `}</style>
          <div
            className="me-dialog relative flex flex-col rounded-2xl overflow-hidden w-full"
            style={{ maxWidth: 720, maxHeight: "90vh", background: C.bg, border: `1px solid ${C.border}`, boxShadow: "0 24px 70px rgba(0,0,0,0.55)" }}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header */}
            <div className="flex items-center justify-between px-5 py-4" style={{ borderBottom: `1px solid ${C.border}` }}>
              <div className="flex items-center gap-2.5">
                <span className="w-9 h-9 rounded-xl inline-flex items-center justify-center" style={{ background: "rgba(253,80,2,0.12)" }}>
                  <Sparkles size={18} style={{ color: C.orange }} />
                </span>
                <div>
                  <h2 className="font-display text-base font-bold" style={{ color: C.text }}>Ekstrak Menu via AI</h2>
                  <p className="text-xs" style={{ color: C.muted }}>Unggah foto / PDF menu, AI baca otomatis</p>
                </div>
              </div>
              <button onClick={closeModal} className="p-1.5 rounded-lg hover:bg-white/10 transition-colors">
                <X size={18} style={{ color: C.muted }} />
              </button>
            </div>

            {/* Body */}
            <div className="overflow-y-auto p-5 flex-1">
              {error && (
                <div className="flex items-start gap-2 mb-4 p-3 rounded-xl text-sm" style={{ background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.25)", color: "#FCA5A5" }}>
                  <AlertCircle size={16} className="shrink-0 mt-0.5" /> {error}
                </div>
              )}

              {/* IDLE — dropzone */}
              {stage === "idle" && (
                <div
                  onClick={() => inputRef.current?.click()}
                  onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={onDrop}
                  className="cursor-pointer rounded-2xl flex flex-col items-center justify-center text-center px-6 py-14 transition-colors"
                  style={{
                    border: `2px dashed ${dragOver ? C.orange : "rgba(255,255,255,0.15)"}`,
                    background: dragOver ? "rgba(253,80,2,0.06)" : C.card,
                  }}
                >
                  <span className="w-14 h-14 rounded-2xl inline-flex items-center justify-center mb-4" style={{ background: "rgba(253,80,2,0.12)" }}>
                    <UploadCloud size={26} style={{ color: C.orange }} />
                  </span>
                  <p className="font-semibold text-sm" style={{ color: C.text }}>
                    Tarik file ke sini, atau klik untuk pilih
                  </p>
                  <p className="text-xs mt-1.5" style={{ color: C.muted }}>JPG · PNG · WEBP · PDF — maks 15MB</p>
                  <input ref={inputRef} type="file" accept=".jpg,.jpeg,.png,.webp,.pdf,image/*,application/pdf" className="hidden" onChange={onPick} />
                </div>
              )}

              {/* PROCESSING — scan animation */}
              {stage === "processing" && (
                <div className="rounded-2xl px-6 py-12 flex flex-col items-center text-center" style={{ background: C.card }}>
                  <style>{`
                    @keyframes me-scan { 0%{top:6%;opacity:1} 50%{top:90%;opacity:1} 51%{opacity:0} 52%{top:6%;opacity:0} 53%{opacity:1} 100%{top:90%;opacity:1} }
                  `}</style>
                  <div className="relative w-24 h-28 rounded-lg overflow-hidden mb-5" style={{ background: "#0B1420", border: `1px solid ${C.border}` }}>
                    <FileText size={40} style={{ color: C.muted, position: "absolute", inset: 0, margin: "auto" }} />
                    <div style={{ position: "absolute", left: 6, right: 6, height: 2, background: `linear-gradient(90deg,transparent,${C.orange},transparent)`, borderRadius: 2, animation: "me-scan 1.8s ease-in-out infinite" }} />
                  </div>
                  <p className="font-semibold text-sm flex items-center gap-2" style={{ color: C.text }}>
                    <Loader2 size={14} className="animate-spin" style={{ color: C.orange }} />
                    Membaca menu…
                  </p>
                  <p className="text-xs mt-1 truncate max-w-[260px]" style={{ color: C.muted }}>{fileName}</p>
                  {/* progress bar */}
                  <div className="w-full max-w-[280px] h-1.5 rounded-full mt-5 overflow-hidden" style={{ background: "rgba(255,255,255,0.08)" }}>
                    <div className="h-full rounded-full transition-all duration-300" style={{ width: `${progress}%`, background: C.orange }} />
                  </div>
                  <p className="text-[11px] mt-2 tabular-nums" style={{ color: C.muted }}>{progress}%</p>
                </div>
              )}

              {/* REVIEW — editable grid */}
              {stage === "review" && (
                <div>
                  <div className="flex items-center justify-between mb-3">
                    <p className="text-sm font-semibold" style={{ color: C.text }}>
                      {drafts.length} item terdeteksi
                    </p>
                    <button onClick={reset} className="text-xs font-medium px-2.5 py-1 rounded-lg" style={{ background: C.card, color: C.muted }}>
                      Ganti file
                    </button>
                  </div>
                  <div className="space-y-2.5">
                    {drafts.map((d) => (
                      <div key={d._id} className="rounded-xl p-3" style={{ background: C.card, border: `1px solid ${C.border}` }}>
                        <div className="flex gap-2">
                          <input
                            value={d.nama_menu}
                            onChange={(e) => updateDraft(d._id, { nama_menu: e.target.value })}
                            placeholder="Nama menu"
                            className="flex-1 min-w-0 px-3 py-2 rounded-lg text-sm font-medium outline-none"
                            style={{ background: C.bg, color: C.text, border: `1px solid ${C.border}` }}
                          />
                          <button
                            onClick={() => removeDraft(d._id)}
                            className="shrink-0 w-9 h-9 inline-flex items-center justify-center rounded-lg transition-colors hover:bg-red-500/15"
                            style={{ color: "#F87171", background: "rgba(239,68,68,0.08)" }}
                            title="Hapus item"
                          >
                            <Trash2 size={15} />
                          </button>
                        </div>
                        <div className="flex gap-2 mt-2">
                          <input
                            value={d.category}
                            onChange={(e) => updateDraft(d._id, { category: e.target.value })}
                            placeholder="Kategori"
                            className="w-1/2 px-3 py-2 rounded-lg text-sm outline-none"
                            style={{ background: C.bg, color: C.text, border: `1px solid ${C.border}` }}
                          />
                          <div className="w-1/2 flex items-center rounded-lg overflow-hidden" style={{ background: C.bg, border: `1px solid ${C.border}` }}>
                            <span className="pl-3 text-sm" style={{ color: C.muted }}>Rp</span>
                            <input
                              type="number"
                              value={d.harga_menu}
                              onChange={(e) => updateDraft(d._id, { harga_menu: Number(e.target.value) || 0 })}
                              placeholder="0"
                              className="flex-1 min-w-0 px-2 py-2 text-sm tabular-nums outline-none bg-transparent"
                              style={{ color: C.text }}
                            />
                          </div>
                        </div>
                        <textarea
                          value={d.description_menu}
                          onChange={(e) => updateDraft(d._id, { description_menu: e.target.value })}
                          placeholder="Deskripsi singkat"
                          rows={2}
                          className="w-full mt-2 px-3 py-2 rounded-lg text-xs outline-none resize-none"
                          style={{ background: C.bg, color: C.text, border: `1px solid ${C.border}` }}
                        />
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* DONE */}
              {stage === "done" && (
                <div className="rounded-2xl px-6 py-14 flex flex-col items-center text-center" style={{ background: C.card }}>
                  <span className="w-16 h-16 rounded-full inline-flex items-center justify-center mb-4" style={{ background: "rgba(34,211,166,0.12)" }}>
                    <CheckCircle2 size={32} style={{ color: C.green }} />
                  </span>
                  <p className="font-display text-lg font-bold" style={{ color: C.text }}>{insertedCount} menu tersimpan!</p>
                  <p className="text-sm mt-1" style={{ color: C.muted }}>Menu baru sudah masuk ke daftar.</p>
                </div>
              )}
            </div>

            {/* Footer actions */}
            {stage === "review" && (
              <div className="flex gap-3 px-5 py-4" style={{ borderTop: `1px solid ${C.border}` }}>
                <button onClick={closeModal} className="flex-1 h-11 rounded-xl text-sm font-semibold" style={{ border: `1px solid ${C.border}`, color: C.muted }}>
                  Batal
                </button>
                <button
                  onClick={save}
                  disabled={pending || drafts.length === 0}
                  className="flex-[2] h-11 rounded-xl text-sm font-bold text-white inline-flex items-center justify-center gap-2 disabled:opacity-60"
                  style={{ background: C.orange }}
                >
                  {pending ? <Loader2 size={15} className="animate-spin" /> : <CheckCircle2 size={15} />}
                  Simpan &amp; Publikasikan ({drafts.length} Menu)
                </button>
              </div>
            )}
            {stage === "done" && (
              <div className="px-5 py-4" style={{ borderTop: `1px solid ${C.border}` }}>
                <button onClick={closeModal} className="w-full h-11 rounded-xl text-sm font-bold text-white" style={{ background: C.orange }}>
                  Selesai
                </button>
              </div>
            )}
          </div>
        </div>,
        document.body
      )}
    </>
  );
}

