            <X size={18} color="#FDFDFD" />
          </button>
          <div className="absolute bottom-0 left-0 right-0 z-[101] px-5 pb-8 pt-12" style={{ background: "linear-gradient(to top, rgba(0,35,85,0.9) 0%, transparent 100%)" }}>
